export function readElement(source, index, copy, fromStorage) {
    return copy(fromStorage(source.get(index)));
}
export function storeElement(target, index, value, copy, toStorage) {
    target.set(index, toStorage(copy(value)));
}
export function storedValues(source, copy, fromStorage, toStorage) {
    const result = [];
    for (let index = 0; index < source.length; index += 1) {
        result.push(toStorage(readElement(source, index, copy, fromStorage)));
    }
    return result;
}
export function orderedCompare(less, equal, left, right) {
    const leftNaN = !equal(left, left);
    const rightNaN = !equal(right, right);
    if (leftNaN) {
        return rightNaN ? 0n : -1n;
    }
    if (rightNaN) {
        return 1n;
    }
    if (less(left, right)) {
        return -1n;
    }
    if (less(right, left)) {
        return 1n;
    }
    return 0n;
}
export function compareLengths(left, right) {
    if (left < right) {
        return -1n;
    }
    if (left > right) {
        return 1n;
    }
    return 0n;
}
